def binding(source, ref, run, env):
    need(re.fullmatch('[0-9a-f]{40}', source or '') and isinstance(ref, str) and ref.startswith('refs/heads/codex/') and re.fullmatch('[1-9][0-9]*', run or ''), 'Root publication/source/ref/run required')
    need(env.get('GITHUB_SHA') == env.get('GITHUB_WORKFLOW_SHA') == source and env.get('GITHUB_REF') == ref and (env.get('GITHUB_RUN_ID') == run) and (env.get('GITHUB_RUN_ATTEMPT') == '1') and (env.get('GITHUB_EVENT_NAME') == 'workflow_dispatch') and (env.get('GITHUB_REPOSITORY') == 'Gabriel-Kahen/cachy-asahi') and (env.get('GITHUB_WORKFLOW_REF') in {'Gabriel-Kahen/cachy-asahi/' + name + '@' + ref for name in ALIASES}), 'exact same-source first-attempt dedicated manual workflow binding')
    token = hashlib.sha256((source + ':' + ref + ':' + run).encode()).hexdigest()[:24]
    return dict(source=source, ref=ref, run=run, attempt=1, token=token)

