def read(path, cap=16 * 1024 ** 2):
    path = Path(path)
    info = path.lstat()
    need(stat.S_ISREG(info.st_mode) and info.st_nlink == 1 and (info.st_size <= cap) and (not any((p.is_symlink() for p in path.parents))), 'bounded ordinary path: ' + str(path))
    return path.read_bytes()
